import{_ as o,r as a,o as l,c as p,e as t,a as i,s as c}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"File Upload Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"File Upload"},"headers":[{"level":2,"title":"Uploading Files","slug":"uploading-files","link":"#uploading-files","children":[]},{"level":2,"title":"Restricting File Types","slug":"restricting-file-types","link":"#restricting-file-types","children":[]},{"level":2,"title":"Thumbnail Options","slug":"thumbnail-options","link":"#thumbnail-options","children":[]}],"relativePath":"4.x/element/form/widget-fileupload.md","filePath":"4.x/element/form/widget-fileupload.md"}'),d={name:"4.x/element/form/widget-fileupload.md"};function r(u,e,g,m,k,h){const s=a("pre-heading"),n=a("post-heading");return l(),p("div",null,[t(s),e[0]||(e[0]=i("h1",null,"File Upload Field",-1)),t(n),e[1]||(e[1]=c(`<p><code>fileupload</code> - renders a file uploader for images or regular files.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">avatar</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Avatar
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">imageHeight</span><span class="token punctuation">:</span> <span class="token number">260</span>
    <span class="token key atrule">imageWidth</span><span class="token punctuation">:</span> <span class="token number">260</span>
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>mode</strong></td><td>the expected file type, either <code>file</code> or <code>image</code>. Default: <code>image</code></td></tr><tr><td><strong>size</strong></td><td>for multiple uploads, the size of the container. Available options: tiny, small, large, huge, giant. Default: <code>large</code></td></tr><tr><td><strong>imageWidth</strong></td><td>if using image type, the preview will be resized to this width, optional.</td></tr><tr><td><strong>imageHeight</strong></td><td>if using image type, the preview will be resized to this height, optional.</td></tr><tr><td><strong>fileTypes</strong></td><td>file extensions that are accepted by the uploader, optional. Eg: <code>zip,txt</code></td></tr><tr><td><strong>mimeTypes</strong></td><td>MIME types that are accepted by the uploader, either as file extension or fully qualified name, optional. Eg: <code>bin,application/octet-stream</code></td></tr><tr><td><strong>maxFilesize</strong></td><td>file size in MB that are accepted by the uploader, optional. Default: from <code>upload_max_filesize</code> php.ini value.</td></tr><tr><td><strong>maxFiles</strong></td><td>maximum number of files allowed to be uploaded.</td></tr><tr><td><strong>useCaption</strong></td><td>allows a title and description to be set for the file. Default: <code>true</code></td></tr><tr><td><strong>thumbOptions</strong></td><td>additional <a href="./../../extend/services/resizer.html">resize options</a> for generating the thumbnail, or pass <code>false</code> to disable thumb generation.</td></tr><tr><td><strong>deferredBinding</strong></td><td>use deferred binding when uploading a file, when available. Disable this to attach the file immediately on upload instead of when saving. Default: <code>true</code></td></tr></tbody></table></div><div class="custom-block tip"><p>Unlike the <a href="./widget-mediafinder.html">Media Finder form widget</a>, the File Upload form widget uses <a href="./../../extend/database/attachments.html">database file attachments</a> so the field name must be that of an <code>attachOne</code> or <code>attachMany</code> relationship attribute on your associated model.</p></div><h2 id="uploading-files"><a href="#uploading-files" class="header-anchor">#</a> Uploading Files</h2><p>Use the <code>mode</code> property set to <code>file</code> to upload documents and other non-image files. You may also want to disable the caption field and set specific file types.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">documents</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Documents
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> file
    <span class="token key atrule">useCaption</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
    <span class="token key atrule">fileTypes</span><span class="token punctuation">:</span> pdf<span class="token punctuation">,</span>docx<span class="token punctuation">,</span>xlsx
</code></pre></div><p>Use the <code>maxFiles</code> property to limit the number of files that can be uploaded. When combined with an <code>attachMany</code> relationship, this allows for multiple file uploads with an upper limit.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">gallery</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Gallery Images
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">maxFiles</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><h2 id="restricting-file-types"><a href="#restricting-file-types" class="header-anchor">#</a> Restricting File Types</h2><p>Use the <code>fileTypes</code> property to specify the allowed file extensions, as a comma-separated list.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">spreadsheet</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Spreadsheet
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> file
    <span class="token key atrule">fileTypes</span><span class="token punctuation">:</span> xls<span class="token punctuation">,</span>xlsx<span class="token punctuation">,</span>csv
</code></pre></div><p>The <code>mimeTypes</code> property can also restrict uploads by MIME type for additional security.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">document</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> PDF Document
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> file
    <span class="token key atrule">fileTypes</span><span class="token punctuation">:</span> pdf
    <span class="token key atrule">mimeTypes</span><span class="token punctuation">:</span> application/pdf
</code></pre></div><div class="custom-block tip"><p>When <code>mode</code> is set to <code>image</code> and no <code>fileTypes</code> are specified, the following image extensions are accepted by default: <strong>avif</strong>, <strong>jpg</strong>, <strong>jpeg</strong>, <strong>bmp</strong>, <strong>png</strong>, <strong>webp</strong>, <strong>gif</strong>, <strong>svg</strong>. These defaults can be customized globally via the <code>media.image_extensions</code> configuration value in <code>config/media.php</code>.</p></div><h2 id="thumbnail-options"><a href="#thumbnail-options" class="header-anchor">#</a> Thumbnail Options</h2><p>Use the <code>thumbOptions</code> property to control how preview thumbnails are generated. This accepts the same options as the <a href="./../../extend/services/resizer.html">image resizer</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">photo</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Photo
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">imageWidth</span><span class="token punctuation">:</span> <span class="token number">300</span>
    <span class="token key atrule">imageHeight</span><span class="token punctuation">:</span> <span class="token number">200</span>
    <span class="token key atrule">thumbOptions</span><span class="token punctuation">:</span>
        <span class="token key atrule">mode</span><span class="token punctuation">:</span> crop
        <span class="token key atrule">extension</span><span class="token punctuation">:</span> png
</code></pre></div><p>To disable thumbnail generation entirely, set <code>thumbOptions</code> to <code>false</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">photo</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Photo
    <span class="token key atrule">type</span><span class="token punctuation">:</span> fileupload
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">thumbOptions</span><span class="token punctuation">:</span> <span class="token boolean important">false</span>
</code></pre></div>`,21))])}const b=o(d,[["render",r]]);export{y as __pageData,b as default};
